style.css:
@-moz-document domain("app.capsitask.com") {
/* ── COLOUR TOKENS ────────────────────────────────────────────────────────── */
:root {
  --ct-bg-0: #0a0d14;
  --ct-bg-1: #0f1320;
  --ct-bg-2: #141929;
  --ct-bg-3: #1c2235;
  --ct-bg-4: #242b3f;

  --ct-accent: #00c8ff;
  --ct-accent-dim: #0a7a99;
  --ct-blue: #4d8fff;
  --ct-green: #00e5a0;
  --ct-pink: #ff4d8f;
  --ct-amber: #ffaa00;
  --ct-purple: #a06bff;

  --ct-text-primary: #e2e8f7;
  --ct-text-secondary: #7a8aaa;
  --ct-text-muted: #4a5570;

  --ct-border: 1px solid var(--ct-bg-4);
  --ct-border-accent: 1px solid var(--ct-accent-dim);
}

*, *::before, *::after {
  scrollbar-color: var(--ct-bg-4) transparent;
  scrollbar-width: thin;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.1s ease !important;
}

body,
#root,
.app-wrapper,
[class*="layout"],
[class*="container"],
[class*="wrapper"] {
  background-color: var(--ct-bg-0) !important;
  color: var(--ct-text-primary) !important;
}

header,
nav,
[class*="header"],
[class*="navbar"],
[class*="topbar"],
[class*="top-bar"] {
  background-color: var(--ct-bg-1) !important;
  border-bottom: var(--ct-border-accent) !important;
  color: var(--ct-text-primary) !important;
  box-shadow: 0 1px 24px rgba(0,200,255,0.06) !important;
}

aside,
[class*="sidebar"],
[class*="side-nav"],
[class*="left-panel"] {
  background-color: var(--ct-bg-1) !important;
  border-right: var(--ct-border-accent) !important;
}

[class*="sidebar"] a,
[class*="sidebar"] span,
[class*="sidebar"] li,
[class*="nav-item"],
[class*="menu-item"] {
  color: var(--ct-text-secondary) !important;
}

[class*="sidebar"] a:hover,
[class*="sidebar"] a.active,
[class*="nav-item"]:hover,
[class*="nav-item"].active,
[class*="menu-item"]:hover,
[class*="menu-item"].active {
  color: var(--ct-accent) !important;
  background-color: rgba(0,200,255,0.07) !important;
}

[class*="sidebar"] a.active,
[class*="nav-item"].active,
[class*="menu-item"].active {
  border-left: 2px solid var(--ct-accent) !important;
}

main,
[class*="main-content"],
[class*="page-content"],
[class*="content-area"] {
  background-color: var(--ct-bg-0) !important;
}

[class*="board"],
[class*="kanban"],
[class*="column-wrap"],
[class*="board-column"],
[class*="swimlane"] {
  background-color: var(--ct-bg-0) !important;
}

[class*="column-header"],
[class*="board-column-header"],
[class*="kanban-column-header"] {
  color: var(--ct-text-primary) !important;
  border-bottom: var(--ct-border-accent) !important;
}

[class*="column-body"],
[class*="card-list"],
[class*="drop-zone"],
[class*="task-list"] {
  background-color: var(--ct-bg-2) !important;
  border: var(--ct-border) !important;
  border-radius: 8px !important;
}

[class*="card"],
[class*="task-card"],
[class*="issue-card"],
[class*="ticket"] {
  background-color: var(--ct-bg-2) !important;
  border: var(--ct-border) !important;
  color: var(--ct-text-primary) !important;
}

[class*="card"]:hover,
[class*="task-card"]:hover {
  border-color: var(--ct-accent-dim) !important;
  background-color: var(--ct-bg-3) !important;
}

[class*="timeline"],
[class*="activity"],
[class*="right-panel"],
[class*="side-panel"] {
  background-color: var(--ct-bg-1) !important;
  border-left: var(--ct-border-accent) !important;
  color: var(--ct-text-primary) !important;
}

[class*="timeline-item"],
[class*="activity-item"] {
  border-bottom: var(--ct-border) !important;
}

[class*="timeline-item"]:hover,
[class*="activity-item"]:hover {
  background-color: var(--ct-bg-3) !important;
}

a,
[class*="ref-no"],
[class*="issue-id"],
[class*="task-id"] {
  color: var(--ct-blue) !important;
}

a:hover {
  color: var(--ct-accent) !important;
}

input,
textarea,
select,
[class*="search"],
[class*="input"] {
  background-color: var(--ct-bg-3) !important;
  border: var(--ct-border) !important;
  color: var(--ct-text-primary) !important;
  caret-color: var(--ct-accent) !important;
}

input:focus,
textarea:focus,
select:focus {
  border-color: var(--ct-accent-dim) !important;
  outline: none !important;
  box-shadow: 0 0 0 2px rgba(0,200,255,0.12) !important;
}

input::placeholder,
textarea::placeholder {
  color: var(--ct-text-muted) !important;
}

[class*="dropdown"],
[class*="popover"],
[class*="menu-list"],
[class*="select-menu"],
[class*="options-list"] {
  background-color: var(--ct-bg-2) !important;
  border: var(--ct-border-accent) !important;
  color: var(--ct-text-primary) !important;
}

[class*="dropdown-item"]:hover,
[class*="option"]:hover,
[class*="menu-list"] li:hover {
  background-color: var(--ct-bg-3) !important;
  color: var(--ct-accent) !important;
}

button,
[class*="btn"] {
  background-color: var(--ct-bg-3) !important;
  border: var(--ct-border) !important;
  color: var(--ct-text-primary) !important;
}

button:hover,
[class*="btn"]:hover {
  background-color: var(--ct-bg-4) !important;
  border-color: var(--ct-accent-dim) !important;
  color: var(--ct-accent) !important;
}

button[class*="primary"],
[class*="btn-primary"] {
  background-color: var(--ct-accent-dim) !important;
  border-color: var(--ct-accent) !important;
  color: #fff !important;
}

button[class*="primary"]:hover,
[class*="btn-primary"]:hover {
  background-color: var(--ct-accent) !important;
  color: #000 !important;
}

[class*="modal"],
[class*="dialog"],
[class*="overlay-content"] {
  background-color: var(--ct-bg-2) !important;
  border: var(--ct-border-accent) !important;
  color: var(--ct-text-primary) !important;
}

[class*="modal-header"],
[class*="dialog-header"] {
  border-bottom: var(--ct-border-accent) !important;
}

[class*="modal-footer"],
[class*="dialog-footer"] {
  border-top: var(--ct-border-accent) !important;
}

[class*="backdrop"],
[class*="modal-backdrop"],
[class*="overlay"]:not([class*="content"]) {
  background-color: rgba(5,8,20,0.75) !important;
}

table {
  background-color: var(--ct-bg-2) !important;
  color: var(--ct-text-primary) !important;
}

th {
  background-color: var(--ct-bg-3) !important;
  color: var(--ct-text-secondary) !important;
  border-bottom: var(--ct-border-accent) !important;
}

td {
  border-bottom: var(--ct-border) !important;
}

tr:hover td {
  background-color: var(--ct-bg-3) !important;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--ct-text-primary) !important;
}

p, span, label, li {
  color: var(--ct-text-secondary) !important;
}

small,
[class*="text-muted"],
[class*="helper-text"],
[class*="subtitle"] {
  color: var(--ct-text-muted) !important;
}

hr,
[class*="divider"] {
  border-color: var(--ct-bg-4) !important;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--ct-bg-4);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--ct-accent-dim);
}

[class*="logo"],
[class*="brand"] {
  filter: brightness(1.2) !important;
}

[class*="avatar"],
[class*="user-icon"],
[class*="person-icon"] {
  background-color: var(--ct-bg-4) !important;
  color: var(--ct-text-secondary) !important;
  border: 1px solid var(--ct-bg-4) !important;
}

[class*="filter-bar"],
[class*="toolbar"],
[class*="action-bar"] {
  background-color: var(--ct-bg-1) !important;
  border-bottom: var(--ct-border) !important;
}

[class*="breadcrumb"] {
  color: var(--ct-text-muted) !important;
}

[class*="breadcrumb"] a {
  color: var(--ct-text-secondary) !important;
}

[class*="breadcrumb"] a:hover {
  color: var(--ct-accent) !important;
}

[class*="paginator"],
[class*="pagination"] {
  background-color: var(--ct-bg-1) !important;
  border-top: var(--ct-border) !important;
  color: var(--ct-text-muted) !important;
}

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--ct-accent) !important;
}
}
